<script setup lang="ts">
import { computed, inject, onMounted, reactive, ref, watch } from "vue";
import { Archive, ArrowClockwise, ArrowLeft, CaretLeft, CaretRight, EnvelopeOpen, FileArrowDown, MagnifyingGlass, PaperPlaneTilt, Plus, Star, Trash, X } from "@phosphor-icons/vue";
import type { APIClient } from "../api";
import { sessionStore } from "../store";

interface Folder { id:string; name:string; unread?:number; role?:string }
interface MailSession { id:string; token:string; expires_at:string }
interface MessageSummary { id:string; folder_id:string; subject:string; from:string; to:string[]; received_at:string; size:number; has_attachments:boolean; flags:string[] }
interface Attachment { id:string; name:string; content_type:string; size:number; download_url?:string }
interface MessageView { summary:MessageSummary; text?:string; sanitized_html?:string; attachments:Attachment[]; remote_images_blocked:boolean }
const api=inject<APIClient>("api")!;const mailboxID=ref("");const mailSession=ref<MailSession|null>(null);const folders=ref<Folder[]>([]);const activeFolder=ref("");const messages=ref<MessageSummary[]>([]);const nextCursor=ref("");const cursors=ref<string[]>([]);const query=ref("");const selected=ref<MessageView|null>(null);const loading=ref(true);const error=ref("");const composeOpen=ref(false);const sending=ref(false);const compose=reactive({to:"",cc:"",subject:"",text:""});
const canCompose=computed(()=>api.available("webmail.message.send"));
onMounted(()=>void bootstrap());watch(activeFolder,()=>{if(activeFolder.value){cursors.value=[];void loadMessages("")}});
async function bootstrap():Promise<void>{loading.value=true;error.value="";try{if(api.available("webmail.mailbox.list")){const response=await api.invoke<unknown>("webmail.mailbox.list",{tenantId:sessionStore.state.tenantId,payload:{limit:100}});const items=collection(response.result);mailboxID.value=String(items[0]?.id||items[0]?.mailbox_id||"")}if(!mailboxID.value)mailboxID.value=localStorage.getItem("panel.webmail.mailbox")||"";if(!mailboxID.value)throw new Error("Select or create a mailbox before opening webmail.");localStorage.setItem("panel.webmail.mailbox",mailboxID.value);mailSession.value=null;await ensureMailSession();await loadFolders()}catch(cause){error.value=cause instanceof Error?cause.message:"Webmail could not be opened."}finally{loading.value=false}}
async function ensureMailSession():Promise<MailSession>{const current=mailSession.value;if(current&&Date.parse(current.expires_at)>Date.now()+30_000)return current;if(!api.available("webmail.session.issue"))throw new Error("Secure webmail sessions are not enabled on this node.");const response=await api.invoke<MailSession>("webmail.session.issue",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{ttl_seconds:900}});if(!response.result.id||!response.result.token||!response.result.expires_at)throw new Error("The node returned an invalid webmail session.");mailSession.value=response.result;return response.result}
async function loadFolders():Promise<void>{if(!api.available("webmail.folder.list"))throw new Error("Webmail is not enabled on this node.");const session=await ensureMailSession();const response=await api.invoke<unknown>("webmail.folder.list",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{session,mailbox_id:mailboxID.value}});folders.value=collection(response.result).map((item)=>({id:String(item.id||item.folder_id),name:String(item.name||item.id),unread:Number(item.unread||0),role:String(item.role||"")}));if(!folders.value.some((folder)=>folder.id===activeFolder.value))activeFolder.value=folders.value.find((folder)=>folder.role==="inbox")?.id||folders.value[0]?.id||""}
async function loadMessages(cursor:string):Promise<void>{loading.value=true;error.value="";selected.value=null;try{const session=await ensureMailSession();const response=await api.invoke<unknown>("webmail.message.list",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{session,mailbox_id:mailboxID.value,folder_id:activeFolder.value,terms:query.value||undefined,cursor:cursor||undefined,limit:75,sort:"newest"}});const page=record(response.result);messages.value=collection(response.result) as unknown as MessageSummary[];nextCursor.value=String(page.next_cursor||"")}catch(cause){error.value=cause instanceof Error?cause.message:"Messages could not be loaded."}finally{loading.value=false}}
async function read(message:MessageSummary):Promise<void>{error.value="";try{const session=await ensureMailSession();const response=await api.invoke<MessageView>("webmail.message.get",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{session,mailbox_id:mailboxID.value,message_id:message.id}});selected.value=response.result;if(!message.flags.includes("seen")&&api.available("webmail.message.flags")){message.flags.push("seen");void api.invoke("webmail.message.flags",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{session,mailbox_id:mailboxID.value,message_id:message.id,flags:message.flags}})}}catch(cause){error.value=cause instanceof Error?cause.message:"Message could not be loaded."}}
async function act(operation:string,message:MessageSummary,payload:Record<string,unknown>={}):Promise<void>{try{const session=await ensureMailSession();await api.invoke(operation,{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{session,mailbox_id:mailboxID.value,message_id:message.id,...payload}});selected.value=null;await loadMessages(cursors.value.at(-1)||"")}catch(cause){error.value=cause instanceof Error?cause.message:"The message operation failed."}}
async function send():Promise<void>{if(!canCompose.value)return;sending.value=true;error.value="";try{const session=await ensureMailSession();await api.invoke("webmail.message.send",{tenantId:sessionStore.state.tenantId,resourceId:mailboxID.value,payload:{session,mailbox_id:mailboxID.value,to:addresses(compose.to),cc:addresses(compose.cc),subject:compose.subject,text:compose.text}});composeOpen.value=false;Object.assign(compose,{to:"",cc:"",subject:"",text:""});sessionStore.notify({tone:"healthy",title:"Message queued",body:"Submission was admitted and can be followed in Queue & delivery."})}catch(cause){error.value=cause instanceof Error?cause.message:"The message could not be submitted."}finally{sending.value=false}}
function search():void{cursors.value=[];void loadMessages("")}function next():void{if(!nextCursor.value)return;cursors.value.push(nextCursor.value);void loadMessages(nextCursor.value)}function previous():void{if(!cursors.value.length)return;cursors.value.pop();void loadMessages(cursors.value.at(-1)||"")}
function download(attachment:Attachment):void{if(!attachment.download_url)return;window.open(attachment.download_url,"_blank","noopener,noreferrer")}
function collection(value:unknown):Record<string,unknown>[]{if(Array.isArray(value))return value.filter(isRecord);const item=record(value);const raw=Array.isArray(item.items)?item.items:Array.isArray(item.results)?item.results:Array.isArray(item.resources)?item.resources:[];return raw.filter(isRecord)}function record(value:unknown):Record<string,unknown>{return isRecord(value)?value:{}}function isRecord(value:unknown):value is Record<string,unknown>{return Boolean(value)&&typeof value==="object"&&!Array.isArray(value)}function addresses(value:string):string[]{return value.split(/[\s,;]+/).map((item)=>item.trim()).filter(Boolean)}function formatDate(value:string):string{const date=new Date(value);return Number.isNaN(date.valueOf())?"":new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short"}).format(date)}function initials(value:string):string{return value.split(/[^a-z0-9]+/i).filter(Boolean).map((part)=>part[0]).join("").slice(0,2).toUpperCase()||"?"}
</script>

<template>
  <main class="webmail-page">
    <header class="mail-head"><div><p>MAILBOX / {{mailboxID||'NOT SELECTED'}}</p><h2>Webmail</h2></div><div><button class="button button-small" type="button" @click="bootstrap"><ArrowClockwise :size="15"/>Refresh</button><button v-if="canCompose" class="button button-primary" type="button" @click="composeOpen=true"><Plus :size="15"/>Compose</button></div></header>
    <div v-if="error" class="mail-error">{{error}}</div>
    <section class="mail-workspace">
      <aside class="folder-list"><button v-for="folder in folders" :key="folder.id" type="button" :class="{active:folder.id===activeFolder}" @click="activeFolder=folder.id"><span>{{folder.name}}</span><small v-if="folder.unread">{{folder.unread}}</small></button></aside>
      <section class="message-list">
        <header><form @submit.prevent="search"><MagnifyingGlass :size="15"/><input v-model="query" type="search" placeholder="Search this folder"/></form><div><button type="button" :disabled="!cursors.length" @click="previous"><CaretLeft :size="16"/></button><button type="button" :disabled="!nextCursor" @click="next"><CaretRight :size="16"/></button></div></header>
        <div v-if="loading" class="mail-loading"><span v-for="i in 9" :key="i" class="skeleton"></span></div>
        <button v-for="message in messages" v-else :key="message.id" type="button" :class="{unread:!message.flags.includes('seen'),active:selected?.summary.id===message.id}" @click="read(message)"><span class="sender-avatar">{{initials(message.from)}}</span><span class="message-copy"><strong>{{message.from}}</strong><b>{{message.subject||'(no subject)'}}</b><small>{{message.to?.join(', ')}}</small></span><span class="message-meta"><time>{{formatDate(message.received_at)}}</time><i><Archive v-if="message.has_attachments" :size="13"/><Star v-if="message.flags.includes('flagged')" :size="13" weight="fill"/></i></span></button>
        <div v-if="!loading&&!messages.length" class="mail-empty"><EnvelopeOpen :size="31"/><strong>No messages</strong><span>This folder is empty.</span></div>
      </section>
      <article v-if="selected" class="message-view">
        <header><button type="button" aria-label="Close message" @click="selected=null"><ArrowLeft :size="17"/></button><div><button v-if="api.available('webmail.message.move')" type="button" title="Archive" @click="act('webmail.message.move',selected.summary,{folder_role:'archive'})"><Archive :size="17"/></button><button v-if="api.available('webmail.message.delete')" type="button" title="Delete" @click="act('webmail.message.delete',selected.summary)"><Trash :size="17"/></button></div></header>
        <div class="message-body"><div class="message-title"><h3>{{selected.summary.subject||'(no subject)'}}</h3><span>{{formatDate(selected.summary.received_at)}}</span></div><div class="address-line"><span class="sender-avatar">{{initials(selected.summary.from)}}</span><div><strong>{{selected.summary.from}}</strong><small>to {{selected.summary.to.join(', ')}}</small></div></div><p v-if="selected.remote_images_blocked" class="image-warning">Remote images are blocked. Use the audited image proxy to load them.</p><div v-if="selected.sanitized_html" class="html-message" v-html="selected.sanitized_html"></div><pre v-else>{{selected.text}}</pre><section v-if="selected.attachments.length" class="attachments"><button v-for="attachment in selected.attachments" :key="attachment.id" type="button" @click="download(attachment)"><FileArrowDown :size="18"/><span><strong>{{attachment.name}}</strong><small>{{attachment.content_type}} · {{attachment.size}} bytes</small></span></button></section></div>
      </article>
      <section v-else class="message-placeholder"><EnvelopeOpen :size="36"/><strong>Select a message</strong><span>Message content is loaded only after an explicit selection.</span></section>
    </section>
    <div v-if="composeOpen" class="compose-layer" @mousedown.self="composeOpen=false"><form class="compose" @submit.prevent="send"><header><div><p>NEW MESSAGE</p><h3>Compose</h3></div><button type="button" aria-label="Close" @click="composeOpen=false"><X :size="18"/></button></header><div class="compose-fields"><label>To<input v-model="compose.to" class="input" required/></label><label>CC<input v-model="compose.cc" class="input"/></label><label>Subject<input v-model="compose.subject" class="input" required/></label><textarea v-model="compose.text" class="textarea" required placeholder="Write a plain-text message…"></textarea></div><footer><button class="button" type="button" @click="composeOpen=false">Cancel</button><button class="button button-primary" type="submit" :disabled="sending"><PaperPlaneTilt :size="16"/>{{sending?'Queuing…':'Send'}}</button></footer></form></div>
  </main>
</template>

<style scoped>
.webmail-page{height:calc(100dvh - var(--topbar));padding:22px clamp(14px,2vw,28px);display:flex;flex-direction:column;min-height:620px}.mail-head{height:63px;display:flex;justify-content:space-between;align-items:flex-start}.mail-head p{margin:0 0 5px;color:var(--accent);font:9px/1 "Panel Mono",monospace;letter-spacing:.12em}.mail-head h2{margin:0;font-size:25px;letter-spacing:-.04em}.mail-head>div:last-child{display:flex;gap:8px}.mail-error{padding:9px 12px;margin-bottom:9px;border-left:3px solid var(--critical);background:color-mix(in srgb,var(--critical),transparent 92%);color:var(--critical);font-size:12px}.mail-workspace{flex:1;min-height:0;display:grid;grid-template-columns:180px minmax(300px,400px) minmax(420px,1fr);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:var(--surface)}.folder-list{padding:12px 8px;background:var(--bg-raised);border-right:1px solid var(--border);overflow:auto}.folder-list button{width:100%;height:36px;border:0;border-radius:6px;background:transparent;color:var(--muted);display:flex;align-items:center;justify-content:space-between;padding:0 10px;cursor:pointer;text-align:left}.folder-list button:hover,.folder-list button.active{background:var(--surface-2);color:var(--text)}.folder-list button.active{box-shadow:inset 2px 0 var(--accent)}.folder-list small{font-family:"Panel Mono",monospace;color:var(--accent)}.message-list{border-right:1px solid var(--border);overflow:auto}.message-list>header{position:sticky;z-index:2;top:0;height:50px;padding:7px;display:flex;gap:7px;background:var(--surface);border-bottom:1px solid var(--border)}.message-list form{flex:1;display:flex;align-items:center;gap:7px;padding:0 9px;border:1px solid var(--border);border-radius:6px;background:var(--bg-raised)}.message-list form input{width:100%;border:0;outline:0;background:transparent;color:var(--text)}.message-list header>div{display:flex}.message-list header>div button,.message-view>header button{width:32px;border:0;background:transparent;color:var(--muted);display:grid;place-items:center;cursor:pointer}.message-list>button{width:100%;min-height:82px;border:0;border-bottom:1px solid var(--border);background:transparent;color:var(--text);display:grid;grid-template-columns:auto 1fr auto;gap:10px;padding:12px;text-align:left;cursor:pointer}.message-list>button:hover,.message-list>button.active{background:var(--surface-2)}.message-list>button.unread{box-shadow:inset 2px 0 var(--accent)}.sender-avatar{width:33px;height:33px;display:grid;place-items:center;border-radius:50%;background:var(--accent-soft);color:var(--accent);font:10px/1 "Panel Mono",monospace}.message-copy{min-width:0;display:grid;gap:4px}.message-copy strong,.message-copy b,.message-copy small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.message-copy strong{font-size:11px}.message-copy b{font-size:12px;font-weight:550}.unread .message-copy b{font-weight:800}.message-copy small,.message-meta{color:var(--subtle);font-size:9px}.message-meta{display:grid;align-content:space-between;justify-items:end}.message-meta i{display:flex;gap:5px;color:var(--warning)}.mail-loading{padding:12px;display:grid;gap:9px}.mail-loading .skeleton{height:62px}.mail-empty,.message-placeholder{height:100%;display:grid;place-content:center;justify-items:center;gap:8px;color:var(--subtle);text-align:center;padding:30px}.mail-empty strong,.message-placeholder strong{color:var(--text)}.message-view{min-width:0;overflow:auto}.message-view>header{height:50px;position:sticky;top:0;z-index:2;border-bottom:1px solid var(--border);background:var(--surface);display:flex;justify-content:space-between;padding:0 10px}.message-view>header>div{display:flex}.message-body{padding:25px clamp(18px,3vw,42px)}.message-title{display:flex;justify-content:space-between;gap:20px}.message-title h3{margin:0;font-size:22px;letter-spacing:-.03em}.message-title span{color:var(--subtle);font-size:10px}.address-line{display:flex;gap:10px;margin:20px 0}.address-line div{display:grid;gap:4px}.address-line small{color:var(--subtle)}.image-warning{padding:8px 10px;background:var(--accent-soft);color:var(--accent);font-size:10px}.html-message{line-height:1.65;overflow-wrap:anywhere}.message-body pre{font:13px/1.65 "Panel Sans",sans-serif;white-space:pre-wrap;overflow-wrap:anywhere}.attachments{display:flex;flex-wrap:wrap;gap:7px;margin-top:24px}.attachments button{border:1px solid var(--border);border-radius:6px;background:var(--surface-2);color:var(--text);display:flex;align-items:center;gap:8px;padding:9px;cursor:pointer}.attachments span{display:grid;gap:3px;text-align:left}.attachments small{color:var(--subtle)}.compose-layer{position:fixed;z-index:75;inset:0;background:rgba(0,5,8,.65);display:grid;place-items:center;padding:20px}.compose{width:min(680px,100%);max-height:90dvh;background:var(--surface);border:1px solid var(--border-strong);border-radius:var(--radius);box-shadow:var(--shadow);display:flex;flex-direction:column}.compose>header{height:67px;padding:0 18px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center}.compose>header p{margin:0 0 5px;color:var(--accent);font:9px/1 "Panel Mono",monospace}.compose h3{margin:0}.compose header button{border:0;background:transparent;color:var(--muted);cursor:pointer}.compose-fields{padding:19px;display:grid;gap:12px;overflow:auto}.compose-fields label{display:grid;grid-template-columns:65px 1fr;align-items:center;font-size:12px}.compose-fields .textarea{min-height:260px}.compose footer{height:65px;border-top:1px solid var(--border);padding:0 18px;display:flex;justify-content:flex-end;align-items:center;gap:8px}
@media(max-width:1100px){.mail-workspace{grid-template-columns:150px minmax(290px,360px) 1fr}}@media(max-width:800px){.webmail-page{height:auto;min-height:calc(100dvh - 56px)}.mail-workspace{min-height:720px;grid-template-columns:130px 1fr}.message-view,.message-placeholder{position:absolute;z-index:4;inset:141px 14px 22px 144px;background:var(--surface);border:1px solid var(--border)}.message-placeholder{display:none}}@media(max-width:560px){.mail-workspace{grid-template-columns:1fr}.folder-list{display:flex;border:0;border-bottom:1px solid var(--border);padding:6px;overflow:auto}.folder-list button{width:auto;min-width:max-content}.message-view{inset:135px 14px 22px}.message-list{border:0}}
</style>
